/* ============================================================================
 * 点数池模块 —— 给「六维 + 一笔预算」这套建卡数值配一套界面与算法
 *
 * 解决的是这一件事：建卡时那六个数字（力量、敏捷……）不是随手填的，它们花的是
 * 一笔预算 —— 可分配点 = 等级 × 每级点数 ＋ 永久奖励。人一边填一边得知道还剩
 * 几点，填完还得对得上；不然封缄之后面板上那个「剩余」当场就是负的。
 *
 * 这一份给四样：
 *   · 一行实时的「可分配 / 已用 / 剩余」，跟着你敲数字走；
 *   · 六格数字输入（写回的就是变量里那六项，走核心那条表单路，不另开一条）；
 *   · 一颗「交给命运」：把剩下的点按职业倾向一次撒开（没填职业就均摊）；
 *   · 六格「临时加成」＋ 一颗写回：加成是六个数的一个对象，**不进池子**。
 *
 * **默认值与卡无关，全都能换。** 六维叫什么、每级几点、职业那一栏叫什么、职业
 * 偏爱哪两项 —— 都在下面那几张表里。卡想换掉它们，在自己的 hud.core.js 的
 * CONFIG 里加一个 pool 块就行，一个字都不用改这里：
 *
 *     pool: {
 *       stats: ['筋骨', '灵巧', '根骨', '悟性', '神识', '气度'],
 *       per: 4,                     // 每级几点
 *       base: 1,                    // 每项从几起步
 *       level: '等级',               // 哪一栏是等级（算池子用）
 *       bonus: '永久奖励',           // 哪一栏并入池子
 *       add: '加成',                 // 临时加成写在哪个对象上
 *       job: '职业',                 // 哪一栏是职业（只用来决定撒点倾向）
 *       jobs: ['剑修', '丹修'],        // 下拉里那几项
 *       favor: { 剑修: ['筋骨', '灵巧'] }   // 职业 -> 偏爱哪两项
 *     }
 *
 * **这一份不写死任何卡名，也不读别的卡的东西。** 池子怎么算、撒得对不对，
 * 全在下面的 自检() 里跟着 测试/run_all.py 一起跑 —— 这几样错了都不报错，
 * 只会安静地把玩家的数值算歪：
 *   · 等级认不出来（空、乱写、0）时按 1 级算，不能让池子变成 NaN 或负数；
 *   · 「已用」只算**高于起点**的那部分，低于起点的项不倒扣；
 *   · 撒出去的点数总和正好等于要撒的点数（不超支也不剩）；
 *   · 加成只认六维那几个键，界面上多出来的东西一个都不写回。
 *
 * 接不接由 hud.conf.json 的「模块」说了算：不接，这个文件根本不在这张卡里。
 * ========================================================================== */
(function () {
  'use strict';

  /* ---------------------------------------------------------------- 默认值 */

  var DEFAULT_STATS = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];

  var DEFAULT_JOBS = ['游侠', '剑士', '斥候', '咒术师', '学者',
                      '神父', '医士', '商人', '铁匠', '矿工'];

  /* 职业偏爱哪两项。认不出的职业 = 没有偏爱 = 六项均摊 —— 宁可均摊，
     也不要替玩家的职业瞎猜一条路。 */
  var DEFAULT_FAVOR = {
    游侠: ['敏捷', '感知'],
    剑士: ['力量', '体质'],
    斥候: ['敏捷', '感知'],
    咒术师: ['智力', '感知'],
    学者: ['智力', '感知'],
    神父: ['魅力', '感知'],
    医士: ['智力', '感知'],
    商人: ['魅力', '智力'],
    铁匠: ['力量', '体质'],
    矿工: ['力量', '体质']
  };

  /* 池子这一套的全部参数，一处读齐。卡没给就全用默认。 */
  function defOf(hud) {
    var cfg = hud.plain(hud.CONFIG && hud.CONFIG.pool) || {};
    var stats = hud.isArr(cfg.stats) ? cfg.stats : [];
    var jobs = hud.isArr(cfg.jobs) ? cfg.jobs : [];
    return {
      per: hud.num(cfg.per, 5),
      base: Math.max(0, Math.round(hud.num(cfg.base, 1))),
      level: hud.str(cfg.level) || '等级',
      bonus: hud.str(cfg.bonus) || '永久奖励',
      add: hud.str(cfg.add) || '加成',
      job: hud.str(cfg.job) || '职业',
      stats: stats.length ? [].slice.call(stats) : DEFAULT_STATS,
      jobs: jobs.length ? [].slice.call(jobs) : DEFAULT_JOBS,
      favor: hud.plain(cfg.favor) || DEFAULT_FAVOR
    };
  }

  /* 一个键一个值的对象（ES5 没有计算属性，只能这样绕一下）。 */
  function oneK(key, value) {
    var o = {};
    o[key] = value;
    return o;
  }

  function setText(node, text) {
    if (node) node.textContent = text == null ? '' : String(text);
  }

  /* 这一层只吃数字，不认 hud —— 认不出的值一律退回第二个参数，
     免得一个乱值（空串、'abc'、undefined）顺着算下去变成 NaN。 */
  function toNum(v, fallback) {
    var n = typeof v === 'number' ? v : parseFloat(String(v == null ? '' : v).trim());
    return isFinite(n) ? n : (fallback == null ? 0 : fallback);
  }

  /* ------------------------------------------------- 池子（不碰 DOM 的那一半） */

  /* 池子大小：等级 × 每级点数 ＋ 永久奖励。
     等级认不出来（空、乱写、0 或负数）时按 1 级算 —— 池子宁可算小，
     也不能因为一个乱值算出 NaN 或负数，那样整页都跟着垮。 */
  function poolOf(def, level, bonus) {
    var lv = Math.round(toNum(level, 1));
    if (!(lv >= 1)) lv = 1;
    return Math.round(lv * def.per + toNum(bonus, 0));
  }

  /* 六维收成一份干净的数：缺的补起点，低于起点的抬回起点。 */
  function statsOf(hud, def, src) {
    var raw = hud.plain(src) || {};
    var out = {};
    for (var i = 0; i < def.stats.length; i++) {
      var k = def.stats[i];
      var v = Math.round(toNum(raw[k], def.base));
      out[k] = v < def.base ? def.base : v;
    }
    return out;
  }

  /* 已用点：六项**高于起点**的那部分之和。
     低于起点的项不倒扣 —— 少给的那个数不是「省下来的点数」，
     扣回去只会让「剩余」莫名其妙地变多。 */
  function spentOf(def, stats) {
    var s = 0;
    for (var i = 0; i < def.stats.length; i++) {
      var v = Math.round(toNum(stats && stats[def.stats[i]], def.base));
      if (v > def.base) s += v - def.base;
    }
    return s;
  }

  /* 撒点权重：六项各 1（保底，谁都有份），被职业偏爱的各再 +2。
     于是「偏爱 : 不偏爱 = 3 : 1」；认不出的职业就是全 1，也就是均摊。 */
  function weightsOf(hud, def, job) {
    var favor = hud.plain(def.favor) || {};
    var hit = favor[hud.str(job)];
    var fav = hud.isArr(hit) ? hit : [];
    var w = [];
    for (var i = 0; i < def.stats.length; i++) {
      var k = def.stats[i], extra = 0;
      for (var j = 0; j < fav.length; j++) {
        if (hud.str(fav[j]) === k) extra = 2;
      }
      w.push(1 + extra);
    }
    return w;
  }

  /* 把 total 点按权重分给六项：最大余数法 —— 先按比例取整，
     剩下的点给小数部分最大的那几项（并列时靠前的先拿）。
     总和**正好**等于 total，不超支也不剩 —— 这条在自检里钉死。 */
  function spread(total, weights) {
    var n = weights.length, out = [], frac = [], i;
    var left = Math.round(toNum(total, 0));
    var sum = 0;
    for (i = 0; i < n; i++) sum += toNum(weights[i], 0);
    if (!(left > 0) || !(sum > 0)) {
      for (i = 0; i < n; i++) out.push(0);
      return out;
    }
    var given = 0;
    for (i = 0; i < n; i++) {
      var ideal = left * toNum(weights[i], 0) / sum;
      var fl = Math.floor(ideal);
      out.push(fl);
      given += fl;
      frac.push(ideal - fl);
    }
    var rest = left - given;
    while (rest > 0) {
      var best = -1;
      for (i = 0; i < n; i++) {
        if (frac[i] >= 0 && (best < 0 || frac[i] > frac[best])) best = i;
      }
      if (best < 0) break;
      out[best] += 1;
      frac[best] = -1;          /* 一项这一轮只多拿一次 */
      rest -= 1;
    }
    return out;
  }

  /* 把 pool 这笔池子按职业倾向一次撒到 stats 上，返回新的六维。
     池子已经超支时一点不撒（不往回削玩家填的数，只如实报出来）。 */
  function spendPool(hud, def, stats, job, pool) {
    var cur = statsOf(hud, def, stats);
    var add = spread(toNum(pool, 0) - spentOf(def, cur), weightsOf(hud, def, job));
    var out = {};
    for (var i = 0; i < def.stats.length; i++) {
      var k = def.stats[i];
      out[k] = cur[k] + toNum(add[i], 0);
    }
    return out;
  }

  /* 临时加成：只认六维那几个键，界面上多出来的框一个都不写回变量；小数取整。 */
  function addsOf(hud, def, obj) {
    var raw = hud.plain(obj) || {};
    var out = {};
    for (var i = 0; i < def.stats.length; i++) {
      var k = def.stats[i];
      out[k] = Math.round(toNum(raw[k], 0));
    }
    return out;
  }

  /* 加成摊成一行人话：「力量+2 敏捷-1」。零的不写，免得一屏都是 +0。 */
  function addListOf(def, adds) {
    var bits = [];
    for (var i = 0; i < def.stats.length; i++) {
      var k = def.stats[i];
      var v = Math.round(toNum(adds && adds[k], 0));
      if (v) bits.push(k + (v > 0 ? '+' : '') + v);
    }
    return bits.join(' ');
  }

  /* ------------------------------------------------------------ 界面那一块 */

  function statCell(hud, def, key, value) {
    return '<label class="hud-pool__cell">' +
      '<span class="hud-pool__cl">' + hud.esc(key) + '</span>' +
      '<input class="hud-input hud-pool__in" type="number" data-field="' + hud.esc(key) +
      '" data-type="number" min="' + def.base + '" step="1" value="' +
      hud.esc(value) + '"></label>';
  }

  /* 加成那几格用 data-add，不是 data-field：它写的是**一个对象**，
     核心那条表单路只认「一个键一个值」，硬塞进去只会写坏。 */
  function addCell(hud, key, value) {
    return '<label class="hud-pool__cell hud-pool__cell--add">' +
      '<span class="hud-pool__cl">' + hud.esc(key) + '</span>' +
      '<input class="hud-input hud-pool__in" type="number" data-add="' + hud.esc(key) +
      '" step="1" value="' + hud.esc(value) + '"></label>';
  }

  function jobSelect(hud, def, job) {
    var cur = hud.str(job);
    var out = '<select class="hud-input" data-field="' + hud.esc(def.job) +
      '" data-type="text"><option value=""' + (cur ? '' : ' selected') +
      '>（不定）</option>';
    for (var i = 0; i < def.jobs.length; i++) {
      var j = hud.str(def.jobs[i]);
      out += '<option value="' + hud.esc(j) + '"' + (j === cur ? ' selected' : '') +
        '>' + hud.esc(j) + '</option>';
    }
    return out + '</select>';
  }

  function barHtml(hud, def, max, used, level, bonus) {
    var left = max - used;
    return '<div class="hud-pool__bar">' +
      '<span class="hud-pool__k">点数池</span>' +
      '<span class="hud-pool__n' + (left < 0 ? ' is-over' : '') + '" data-pool-left>' +
      (left < 0 ? '超支 ' + (-left) : '剩余 ' + left) + '</span>' +
      '<span class="hud-pool__of">可分配 <b data-pool-max>' + max +
      '</b>　已用 <b data-pool-used>' + used + '</b></span>' +
      '<span class="hud-pool__eq">＝ 等级 <b data-pool-lv>' + level + '</b> × ' +
      def.per + ' ＋ ' + hud.esc(def.bonus) + ' <b data-pool-bonus>' + bonus + '</b></span>' +
      '</div>';
  }

  function createBlock(hud, state) {
    var def = defOf(hud);
    var p = hud.objectOf(state, hud.CONFIG.playerObject);
    var level = Math.max(1, Math.round(toNum(p[def.level], 1)));
    var bonus = Math.round(toNum(p[def.bonus], 0));
    var max = poolOf(def, level, bonus);
    var stats = statsOf(hud, def, p);
    var adds = addsOf(hud, def, p[def.add]);
    var head = [], tail = [];
    for (var i = 0; i < def.stats.length; i++) {
      var k = def.stats[i];
      head.push(statCell(hud, def, k, stats[k]));
      tail.push(addCell(hud, k, adds[k]));
    }
    return '' +
      '<div class="hud-pool" data-pool>' +
      barHtml(hud, def, max, spentOf(def, stats), level, bonus) +
      '  <div class="hud-pool__grid">' + head.join('') + '</div>' +
      '  <div class="hud-pool__row">' +
      '    <label class="hud-pool__side"><span class="hud-pool__cl">' + hud.esc(def.job) +
      '</span>' + jobSelect(hud, def, p[def.job]) + '</label>' +
      '    <label class="hud-pool__side"><span class="hud-pool__cl">' + hud.esc(def.bonus) +
      '</span><input class="hud-input hud-pool__in" type="number" data-field="' +
      hud.esc(def.bonus) + '" data-type="number" min="0" step="1" value="' +
      bonus + '"></label>' +
      '  </div>' +
      '  <div class="hud-pool__acts">' +
      '    <button type="button" class="hud-btn hud-btn--quiet" data-act="pool-fate"' +
      ' title="按职业倾向，把剩下的点数一次撒到那六项上">交给命运</button>' +
      '    <button type="button" class="hud-btn hud-btn--quiet" data-act="pool-write"' +
      ' title="把下面那六格临时加成写进变量（不进点数池）">加成写回</button>' +
      '  </div>' +
      '  <div class="hud-pool__addbox">' +
      '    <div class="hud-pool__al">临时加成 · 不进池子，只影响判定，事过即还</div>' +
      '    <div class="hud-pool__grid">' + tail.join('') + '</div>' +
      '  </div>' +
      '  <div class="hud-pool__note" data-pool-note hidden></div>' +
      '</div>';
  }

  /* 面板上那一行：已有角色时才画。没角色的卡不该多一行「剩余 5」，
     那会让人以为这一局已经开工了。 */
  function panelBlock(hud, state) {
    if (!hud.hasProfile(state)) return '';
    var def = defOf(hud);
    var p = hud.objectOf(state, hud.CONFIG.playerObject);
    var max = poolOf(def, p[def.level], p[def.bonus]);
    var used = spentOf(def, statsOf(hud, def, p));
    var left = max - used;
    var adds = addListOf(def, addsOf(hud, def, p[def.add]));
    return '' +
      '<div class="hud-poolhint">' +
      '<span class="hud-poolhint__n">点数池 ' + (left < 0 ? '超支 ' + (-left) : '剩余 ' + left) +
      '</span>' +
      '<span class="hud-poolhint__of">可分配 ' + max + ' · 已用 ' + used + '</span>' +
      (adds ? '<span class="hud-poolhint__a">' + hud.esc(def.add) + ' ' +
        hud.esc(adds) + '</span>' : '') +
      '</div>';
  }

  function noteIn(pool, text, kind) {
    var n = pool.querySelector('[data-pool-note]');
    if (!n) return;
    n.hidden = !text;
    n.className = 'hud-pool__note' + (kind ? ' ' + kind : '');
    n.textContent = text || '';
  }

  /* 从被点的那个扣子往上找，找到带着某个标记的那一层 ——
     读表单、写状态提示都收在这一块里做，不碰页面别处。 */
  function upTo(node, attr) {
    var t = node;
    while (t && t.getAttribute && !t.getAttribute(attr)) t = t.parentNode;
    return (t && t.getAttribute) ? t : null;
  }

  function fieldEl(create, key) {
    var list = create.querySelectorAll('[data-field]');
    for (var i = 0; i < list.length; i++) {
      if (list[i].getAttribute('data-field') === key) return list[i];
    }
    return null;
  }

  /* 表单里现在这一份：池子多大、花了多少。读的是**界面**上的数，
     不是变量里的 —— 人正敲着，看到的必须是敲进去的。 */
  function readBar(hud, def, create) {
    var got = hud.readCreateForm(create);
    var level = Math.max(1, Math.round(toNum(got[def.level], 1)));
    var bonus = Math.round(toNum(got[def.bonus], 0));
    var stats = {};
    for (var i = 0; i < def.stats.length; i++) {
      var k = def.stats[i];
      var v = Math.round(toNum(got[k], def.base));
      stats[k] = v < def.base ? def.base : v;
    }
    var max = poolOf(def, level, bonus);
    return { level: level, bonus: bonus, stats: stats, max: max,
             used: spentOf(def, stats), job: hud.str(got[def.job]) };
  }

  function paint(pool, it) {
    var left = it.max - it.used;
    var n = pool.querySelector('[data-pool-left]');
    setText(n, left < 0 ? '超支 ' + (-left) : '剩余 ' + left);
    if (n) n.className = 'hud-pool__n' + (left < 0 ? ' is-over' : '');
    setText(pool.querySelector('[data-pool-max]'), it.max);
    setText(pool.querySelector('[data-pool-used]'), it.used);
    setText(pool.querySelector('[data-pool-lv]'), it.level);
    setText(pool.querySelector('[data-pool-bonus]'), it.bonus);
  }

  /* 交给命运：按职业倾向把剩下的点一次撒开。
     撒的是界面那六格 —— 撒完还能手调，封缄时以界面上的数为准。 */
  function doFate(hud, create, pool) {
    var def = defOf(hud);
    var it = readBar(hud, def, create);
    var left = it.max - it.used;
    if (left <= 0) {
      noteIn(pool, left === 0
        ? '点数已经花完了 —— 想重撒，先把某一项调低一点，或者把等级加上去，再点这颗扣子。'
        : '点数已经超支 ' + (-left) + ' —— 先把六维削回池子里，再点这颗扣子。');
      return;
    }
    var out = spendPool(hud, def, it.stats, it.job, it.max);
    var bits = [];
    for (var i = 0; i < def.stats.length; i++) {
      var k = def.stats[i];
      var el = fieldEl(create, k);
      if (el) el.value = out[k];
      bits.push(k + ' ' + out[k]);
    }
    paint(pool, readBar(hud, def, create));
    noteIn(pool, '已按' + (it.job ? '「' + it.job + '」的倾向' : '不偏（职业那栏空着）') +
      '把 ' + left + ' 点撒开：' + bits.join(' · ') +
      '。还能手调 —— 封缄时以界面上的数为准。', 'is-ok');
  }

  /* 加成写回：那六个数住在变量里的**一个对象**上，表单那条路送不进去，
     所以这里自己走一次写变量。只在玩家点这颗扣子时写 ——
     跟着「封缄」一起写，会和核心那一次互相踩（两次读到的状态不一样）。 */
  function doWriteAdds(hud, pool) {
    var def = defOf(hud);
    var inputs = pool.querySelectorAll('[data-add]');
    var raw = {};
    for (var i = 0; i < inputs.length; i++) {
      var k = inputs[i].getAttribute('data-add');
      if (k) raw[k] = inputs[i].value;
    }
    var adds = addsOf(hud, def, raw);
    noteIn(pool, '正在把临时加成写进变量…');
    return hud.writeObject(hud.CONFIG.playerObject, oneK(def.add, adds), pool)
      .then(function (warn) {
        noteIn(pool, warn ? warn
          : '临时加成已写进「' + def.add + '」：' + (addListOf(def, adds) || '六项都是 0') +
            '。它不进点数池 —— 属性是长在身上的，加成是事过即还的。',
          warn ? 'is-error' : 'is-ok');
      })
      .catch(function (err) {
        noteIn(pool, '加成没写进变量：' + hud.msgOf(err), 'is-error');
      });
  }

  /* ------------------------------------------------------------------ 接线 */

  function register() {
    var hud = window.CARDC73C60_HUD;
    if (!hud || typeof hud.useModule !== 'function') return;

    hud.useModule({
      name: '点数池',
      /* 建卡器：档位那一行底下、表单与「封缄」之间 */
      create: function (state) { return createBlock(hud, state); },
      /* 面板：已有角色时多一行「剩余 / 加成」 */
      panel: function (state) { return panelBlock(hud, state); },
      mount: function (h) {
        var use = h || hud;
        /* 一边敲一边算：六格数字、职业、永久奖励、等级，动哪个都重算那一行。
           input 管打字，change 管下拉与上下箭头 —— 两个都收。 */
        var live = function (ev) {
          var create = upTo(ev.target, 'data-create');
          if (!create) return;
          var pool = create.querySelector('[data-pool]');
          if (!pool) return;
          paint(pool, readBar(use, defOf(use), create));
        };
        document.addEventListener('input', live);
        document.addEventListener('change', live);
        document.addEventListener('click', function (ev) {
          var t = ev.target;
          while (t && t.getAttribute && !t.getAttribute('data-act')) t = t.parentNode;
          if (!t || !t.getAttribute) return;
          var act = t.getAttribute('data-act');
          /* 核心的「清空」把表单全抹空 —— 那一行得跟着重算，
             不然它停在上一秒的剩余上，人以为没清掉。 */
          if (act === 'reset') {
            var root = upTo(t, 'data-create');
            var box = root && root.querySelector('[data-pool]');
            if (box) {
              setTimeout(function () { paint(box, readBar(use, defOf(use), root)); }, 0);
            }
            return;
          }
          if (act !== 'pool-fate' && act !== 'pool-write') return;
          var pool = upTo(t, 'data-pool');
          var create = upTo(t, 'data-create');
          if (!pool || !create) return;
          ev.preventDefault();
          if (act === 'pool-fate') doFate(use, create, pool);
          else doWriteAdds(use, pool);
        });
      },
      自检: function () {
        var def = defOf(hud);
        var n = def.stats.length;
        var i, k;

        /* 一份全在起点的六维，与它的一个变体（第一项 +3） */
        var full = {}, one = {};
        for (i = 0; i < n; i++) {
          full[def.stats[i]] = def.base;
          one[def.stats[i]] = def.base;
        }
        one[def.stats[0]] = def.base + 3;

        /* 均摊 vs 有倾向：给同样的 10 点，看撒出来的样子 */
        var even = spread(10, weightsOf(hud, def, '这个职业不存在'));
        var bias = spread(10, weightsOf(hud, def, hud.str(def.jobs[0])));

        /* 偏爱的那几格 / 不偏爱的其余几格 */
        var hit = (hud.plain(def.favor) || {})[hud.str(def.jobs[0])];
        var fav = hud.isArr(hit) ? hit.map(hud.str) : [];
        var atFav = [], atOther = [];
        for (i = 0; i < n; i++) {
          if (fav.indexOf(def.stats[i]) >= 0) atFav.push(i); else atOther.push(i);
        }
        var pick = function (a, idx) {
          var s = 0;
          for (var j = 0; j < idx.length; j++) s += a[idx[j]];
          return s;
        };
        var sum = function (a) {
          var s = 0;
          for (var j = 0; j < a.length; j++) s += a[j];
          return s;
        };
        var hi = function (a) { return Math.max.apply(null, a); };
        var lo = function (a) { return Math.min.apply(null, a); };

        /* 池子已经超支：一件都不该被削回来 */
        var fat = {};
        for (i = 0; i < n; i++) fat[def.stats[i]] = def.base + 5;
        var fatSpent = spentOf(def, fat);
        var stayed = spendPool(hud, def, fat, '', fatSpent - 4);

        var pool5 = poolOf(def, 5, 0);
        var fated = spendPool(hud, def, full, '', pool5);
        var stray = addsOf(hud, def, oneK('这个键不存在', 9));

        /* 面板那两条断言得先有一份「有角色」的变量：hasProfile 只看有没有名字 */
        var withName = oneK('姓名', '甲');
        var withAdds = oneK('姓名', '甲');
        withAdds[def.add] = oneK(def.stats[0], 3);

        return [
          ['池子大小 = 等级 × 每级点数 ＋ 永久奖励',
            poolOf(def, 5, 0) === 5 * def.per && poolOf(def, 3, 7) === 3 * def.per + 7],
          ['等级认不出来时按 1 级算（不吐 NaN、不吐负数）',
            poolOf(def, '乱写', 0) === def.per && poolOf(def, 0, 0) === def.per &&
            poolOf(def, null, 0) === def.per && poolOf(def, -9, 0) === def.per &&
            !isNaN(poolOf(def, undefined, 0))],
          ['六项都在起点时一点没花', spentOf(def, full) === 0],
          ['已用点 = 六项高于起点的部分之和', spentOf(def, one) === 3],
          ['低于起点的项不倒扣（剩余不会莫名其妙变多）',
            spentOf(def, oneK(def.stats[0], def.base - 5)) === 0 && spentOf(def, {}) === 0],
          ['撒出去的点数总和正好等于给的点数',
            sum(even) === 10 && sum(bias) === 10 && sum(spread(0, [1, 1, 1])) === 0],
          ['没得撒的时候一点不撒（不往回削，也不炸）',
            sum(spread(-3, [1, 1])) === 0 && sum(spread(2, [0, 0])) === 0],
          ['不偏时六项差距不超过 1', hi(even) - lo(even) <= 1],
          ['有倾向时偏爱的那两项拿得更多、其余跟着少',
            !atFav.length ||
            (pick(bias, atFav) > pick(even, atFav) &&
             hi(atOther.map(function (x) { return bias[x]; })) <=
             hi(atOther.map(function (x) { return even[x]; })))],
          ['「交给命运」把剩余一次花完：撒完正好等于池子大小',
            spentOf(def, fated) === pool5],
          ['池子已经超支时，交给命运一点不撒（不削玩家填的数）',
            spentOf(def, stayed) === fatSpent],
          ['加成只认六维那几个键，界面上多出来的框一个都不写回',
            Object.keys(stray).length === n && stray['这个键不存在'] === undefined &&
            stray[def.stats[0]] === 0],
          ['加成取整：小数四舍五入，乱写当 0',
            addsOf(hud, def, oneK(def.stats[0], 2.6))[def.stats[0]] === 3 &&
            addsOf(hud, def, oneK(def.stats[0], '乱写'))[def.stats[0]] === 0],
          ['加成列成一行时零的不写',
            addListOf(def, oneK(def.stats[0], 0)) === '' &&
            addListOf(def, oneK(def.stats[0], 2)).indexOf(def.stats[0]) === 0],
          ['没有角色的卡：面板那一块不画（不给空卡添一行）',
            panelBlock(hud, {}) === ''],
          ['有角色时画得出「剩余」那一行',
            panelBlock(hud, { stat_data: oneK(hud.CONFIG.playerObject,
              withName) }).indexOf('剩余') >= 0],
          ['加成会出现在面板那一行上（带着那一栏的名字）',
            panelBlock(hud, { stat_data: oneK(hud.CONFIG.playerObject,
              withAdds) }).indexOf(def.add) >= 0]
        ];
      }
    });
  }

  register();
})();

/* ============================================================================
 * 代笔模块 —— 把一栏「交给 AI 起一版」，再把 AI 回的那一块搬进栏里
 *
 * 卡里没有第二条通道能让 AI 把文字交回界面：它能写的地方只有对话。
 * 所以这一套走的是对话那条路，规矩定死在两处：
 *   · 请求：一段带记号（AI_REQ_MARK）的正文，末尾写明「只回【代笔 · 栏位名】这一块」；
 *   · 回话：AI 照那一块回，界面从**最后一条**消息里切出【代笔 · 栏位名】，
 *     塞回对应的那一栏 —— 搬进去之后照样能手改。
 *
 * **这一份也不写死栏位名。** 建卡器有哪几栏（hud.CONFIG.fields），这里就摆几对
 * 「AI 代笔 / 取回」扣子；栏的类型决定请求里怎么写、回话怎么切：
 *   · 一行文本 → 压成一行，剥掉引号与「一行：」那种壳，掐到 TEXT_CAP；
 *   · 数字     → 只认一个数，按那一栏的上下限夹住（表单是同一套上下限）；
 *   · 一行一件 → 按行 / 顿号 / 逗号切开，剥编号与圆点，去重，掐到 LIST_CAP。
 * 哪一栏不想让 AI 碰，把它的 key 写进下面的 SKIP —— 别的一字不用改。
 *
 * 回话怎么认（三道闸，缺一条就会把旧回复或自己的请求搬进栏里）：
 *   1. 不是空的；2. 不是我们自己发出去的那份请求；3. 跟按下去那一刻的末条不一样。
 * 认下来之后自动搬 —— 每 2.5 秒看一眼宿主最后一条消息；宿主肯转发
 * agent.run.finished 事件时就更快，不转也照样兜得住。
 *
 * 送出去有两条路，只看宿主的接口通哪条：
 *   · input.set  → 只填进对话输入框，由玩家自己按发送（**默认**，不会把人从建卡器卷走）；
 *   · chat.send  → 直接发。要玩家自己拨开关换成这条。
 * 两条都不通时界面如实说：把请求整段复制给 AI，回完点「取回」。
 *
 * 自检写在下面 自检() 里，测的是「切与认」那一半：块切错、清单切不干净、
 * 自家人发出去的请求被当成回复 —— 这三样都不报错，只会安静地把栏填坏。
 * ========================================================================== */
(function () {
  'use strict';

  /* 我们自己发出去的请求里必带这一句。末条消息里若是它，说明 AI 还没回 ——
     没有这个记号，「取回」会把我们自己写的那份格式模板当成回复搬进栏里。 */
  var MARK = '（这是建卡器发来的代笔请求';

  var TEXT_CAP = 60;        /* 一行文本的栏：最多留这么长 */
  var LIST_CAP = 8;         /* 「一行一件」的栏：最多留这么多条 */
  var POLL_MS = 2500;       /* 等回话时多久看一眼最后一条消息 */
  var WAIT_SENT_MS = 120000;  /* 请求已经发出去了：两分钟没回就松开扣子 */
  var WAIT_HOLD_MS = 600000;  /* 只填进输入框：给玩家十分钟按发送 */

  /* 哪几栏不让 AI 碰（写 hud.CONFIG.fields 里的 key）。
     默认一个都不跳 —— 「等级」「钱币」这种数字栏也给得：请求里只要一个数字，
     回话照样按上下限夹住，玩家不满意自己改就是了。 */
  var SKIP = [];

  /* ------------------------------------------------- 切与认（不碰 DOM 的那一半） */

  /* 从一段文本里切出所有【代笔 · 栏位名】块。一次问了好几栏就切出好几块 ——
     「取回全部」靠它一次搬完。 */
  function parseBlocks(text) {
    var s = String(text == null ? '' : text);
    var re = /【代笔\s*·\s*([^】\n]{1,12})】/g;
    var m, marks = [], out = {};
    while ((m = re.exec(s)) !== null) {
      marks.push({ label: m[1].replace(/\s+/g, ''), head: m.index, end: m.index + m[0].length });
    }
    for (var i = 0; i < marks.length; i++) {
      var stop = marks[i + 1] ? marks[i + 1].head : s.length;
      out[marks[i].label] = s.slice(marks[i].end, stop);
    }
    return out;
  }

  /* 这条回复能不能收。三条一起判：不是空的、不是我们自己那份请求、
     也不是「按下扣子那一刻就已经摊在那儿」的那一条 ——
     少了最后一条，重复点同一栏会把上一轮的旧回复再搬一遍，看着像成了，其实没有。 */
  function acceptable(text, base) {
    var s = String(text == null ? '' : text).trim();
    if (!s) return false;
    if (s.indexOf(MARK) >= 0) return false;
    if (base && s === String(base).trim()) return false;
    return true;
  }

  /* 「一行一件」的栏：按行、顿号、逗号、分号、斜线切开，剥掉行首的编号与圆点，
     去重去空，掐掉超长项，最后按 cap 截断。AI 爱写成「1. 追踪」或「· 弓术」，
     那两种壳都在这里剥掉。 */
  function splitList(hud, raw, cap) {
    var parts = String(raw == null ? '' : raw).split(/[\n\r；;、，,\/／|]+/);
    var out = [], seen = {};
    for (var i = 0; i < parts.length; i++) {
      var v = parts[i]
        .replace(/^[\s\-–—·•*・\d.．、)）(（【】[\]]+/, '')
        .replace(/[\s。.！!]+$$/, '')
        .trim();
      if (!v || v.length > 24) continue;
      if (seen[v]) continue;
      seen[v] = 1;
      out.push(v);
      if (out.length >= Math.max(1, hud.num(cap, 1))) break;
    }
    return out;
  }

  /* 单行栏：压成一行的空格，剥掉 AI 爱加的引号、书名号与「一行：」这类壳。 */
  function oneLine(raw, cap) {
    var s = String(raw == null ? '' : raw).replace(/\s+/g, ' ').trim();
    s = s.replace(/^[「『"'“‘]+/, '').replace(/[」』"'”’]+$$/, '');
    s = s.replace(/^[（(【\[]?\s*(一行|答案|结果|不超过\s*\d+\s*字)\s*[:：]?\s*/, '');
    s = s.replace(/[，,、；;。]+$$/, '').trim();
    if (cap && s.length > cap) s = s.slice(0, cap);
    return s;
  }

  function pickText(m) {
    return String((m && (m.content || m.text || m.message)) || '');
  }

  /* 末条可读的正文。空消息（宿主偶尔留白）跳过。 */
  function lastSay(list) {
    if (!list || !list.length) return '';
    for (var i = list.length - 1; i >= 0; i--) {
      var s = pickText(list[i]).trim();
      if (s) return s;
    }
    return '';
  }

  /* 这一版宿主该怎么把请求送出去。两条路都通时看玩家拨的开关：
     拨到「直接发」就走 chat.send，否则只填进输入框。
     只通一条就走那一条；都不通返回空串，界面如实说，让玩家自己复制。 */
  function sendMode(caps, direct) {
    var canChat = !!(caps && caps.chat);
    var canInput = !!(caps && caps.input);
    if (!canChat && !canInput) return '';
    if (!canInput) return 'chat';
    if (!canChat) return 'input';
    return direct ? 'chat' : 'input';
  }

  /* 建卡器上要摆代笔扣子的那几栏，从 CONFIG.fields 现读。 */
  function slots(hud) {
    var out = [], F = hud.CONFIG.fields || [];
    for (var i = 0; i < F.length; i++) {
      var f = F[i];
      if (SKIP.indexOf(f.key) >= 0) continue;
      out.push({
        key: f.key, label: f.label || f.key, kind: f.type,
        min: f.min, max: f.max, tip: f.hint || ''
      });
    }
    return out;
  }

  /* 按栏位名（或者栏位 key —— AI 偶尔照 key 写）找那一栏 */
  function slotOf(hud, name) {
    var all = slots(hud), s = String(name == null ? '' : name).trim();
    for (var i = 0; i < all.length; i++) {
      if (all[i].label === s || all[i].key === s) return all[i];
    }
    return null;
  }

  /* 写进请求里的那句「要什么」。谁定的？这一栏的类型定的 —— 不另外维护一张表。 */
  function wantOf(s) {
    if (s.kind === 'list') return '3 – 6 条，一条一行';
    if (s.kind === 'number') {
      var lo = (s.min == null) ? '' : String(s.min);
      var hi = (s.max == null) ? '' : String(s.max);
      var range = (lo || hi) ? '（' + (lo || '不限') + ' – ' + (hi || '不限') + '）' : '';
      return '只回一个数字' + range;
    }
    return '一行，不超过 40 字';
  }

  function tipOf(s) {
    if (s.tip) return s.tip;
    if (s.kind === 'list') return '只写条目本身，不写解释、不给数值';
    if (s.kind === 'number') return '只回数字，不要任何说明';
    return '照这一栏的名字写，写看得见的东西，不要写成一段故事';
  }

  /* ------------------------------------------------------------ 界面那一块 */

  function barHtml(hud, s) {
    return '<div class="hud-ai__row">' +
      '<span class="hud-ai__l">' + hud.esc(s.label) + '</span>' +
      '<button type="button" class="hud-btn hud-btn--quiet" data-act="ai" data-slot="' +
      hud.esc(s.key) + '">AI 代笔</button>' +
      '<button type="button" class="hud-btn hud-btn--quiet" data-act="ai-take" data-slot="' +
      hud.esc(s.key) + '">取回</button>' +
      '<span class="hud-ai__hint">' + hud.esc(wantOf(s)) + '</span>' +
      '</div>';
  }

  function blockHtml(hud, state) {
    var all = slots(hud), rows = [];
    for (var i = 0; i < all.length; i++) rows.push(barHtml(hud, all[i]));
    return '' +
      '<div class="hud-ai" data-ai>' +
      '  <div class="hud-ai__t">AI 代笔</div>' +
      '  <div class="hud-ai__lead">让它先给一版，你再改 —— 取回来的内容跟手打进去的没有两样。' +
      '点某一栏的「AI 代笔」，请求会填进对话输入框（或直接发出去），AI 回完自动搬进那一栏。' +
      '</div>' +
      '  <div class="hud-ai__top">' +
      '    <button type="button" class="hud-btn hud-btn--quiet" data-act="ai-direct">' +
      '代笔：只填不送</button>' +
      '    <button type="button" class="hud-btn hud-btn--quiet" data-act="ai-all">取回全部</button>' +
      '  </div>' +
      '  <div class="hud-ai__rows">' + rows.join('') + '</div>' +
      '  <div class="hud-ai__out" data-ai-out hidden></div>' +
      '  <div class="hud-ai__note" data-ai-note hidden></div>' +
      '</div>';
  }

  function noteIn(root, text, kind) {
    var n = root.querySelector('[data-ai-note]');
    if (!n) return;
    n.hidden = !text;
    n.className = 'hud-ai__note' + (kind ? ' ' + kind : '');
    n.textContent = text || '';
  }

  /* 请求摊在这儿：宿主不给代发、也填不了输入框时，玩家能自己整段复制走。 */
  function outIn(root, html) {
    var box = root.querySelector('[data-ai-out]');
    if (!box) return;
    box.hidden = !html;
    box.innerHTML = html || '';
  }

  function createRootOf(node) {
    var t = node;
    while (t && t.getAttribute && !t.getAttribute('data-create')) t = t.parentNode;
    return (t && t.getAttribute) ? t : null;
  }

  /* 每一处建卡器各自记一份状态（等待中的栏、基线末条、定时器、开关）——
     挂在根元素上，页面里有两处建卡器也不会互相串。 */
  function stOf(root) {
    if (!root.__hudAi) {
      root.__hudAi = { waiting: {}, base: {}, timers: {}, poll: null,
        direct: false, lastReq: '', evBound: false };
    }
    return root.__hudAi;
  }

  function btnOf(root, act, key) {
    var list = root.querySelectorAll('[data-act="' + act + '"]');
    for (var i = 0; i < list.length; i++) {
      if (list[i].getAttribute('data-slot') === key) return list[i];
    }
    return null;
  }

  /* 这一栏现在写着什么 —— 有内容就润色，空着就现写 */
  function valueOf(hud, root, s) {
    var got = hud.readCreateForm(root)[s.key];
    if (s.kind === 'list') return hud.isArr(got) ? got.join('、') : hud.str(got);
    return hud.str(got);
  }

  /* 给 AI 的上下文：他已经填了什么。填得越全，代笔出来的越像这个人。 */
  function contextOf(hud, root) {
    var form = hud.readCreateForm(root), bits = [], all = slots(hud);
    for (var i = 0; i < all.length; i++) {
      var s = all[i], v = form[s.key];
      var text = hud.isArr(v) ? v.join('、') : hud.str(v);
      if (!text) continue;
      if (s.kind === 'number' && s.min != null && hud.num(text, s.min) === s.min) continue;  /* 没动过的下限值不算填过 */
      bits.push(s.label + ' ' + text);
    }
    return bits.length ? bits.join('；') : '（还什么都没填）';
  }

  /* -------------------------------------------------- 「生成中…」与自动取回 */

  function pendingKeys(st) {
    var out = [];
    Object.keys(st.waiting).forEach(function (k) { if (st.waiting[k]) out.push(k); });
    return out;
  }

  /* 按下去这一刻，末条是什么。存着用来认「后来这条才是新回的」。 */
  function snapshot(hud, st, key) {
    st.base[key] = '';
    var e = hud.api();
    if (!e || !e.messages || typeof e.messages.list !== 'function') return Promise.resolve();
    return Promise.resolve().then(function () { return e.messages.list(); })
      .then(function (list) { st.base[key] = lastSay(list); })
      .catch(function () { /* 读不到就当没有基线：MARK 那道闸还在 */ });
  }

  function waitOn(hud, root, st, key, hold) {
    st.waiting[key] = hold ? 'hold' : 'sent';
    var btn = btnOf(root, 'ai', key);
    if (btn) {
      btn.disabled = true;
      btn.classList.add('is-waiting');
      if (hold) btn.classList.add('is-hold');
      btn.textContent = hold ? '待发送' : '生成中…';
    }
    if (st.timers[key]) clearTimeout(st.timers[key]);
    st.timers[key] = setTimeout(function () {
      delete st.timers[key];
      waitOff(hud, root, st, key);
      noteIn(root, hold
        ? '代笔请求还压在对话输入框里没发出去（等了十分钟），先把扣子松开。'
        : '等了两分钟还没等到 AI 的回复。它要是后来回了，点那一栏的「取回」照样能搬进来。',
        'is-error');
    }, hold ? WAIT_HOLD_MS : WAIT_SENT_MS);
    bindRunEvents(hud, root, st);
    pollStart(hud, root, st);
  }

  function waitOff(hud, root, st, key) {
    if (st.timers[key]) { clearTimeout(st.timers[key]); delete st.timers[key]; }
    if (!st.waiting[key]) return;
    delete st.waiting[key];
    var btn = btnOf(root, 'ai', key);
    if (btn) {
      btn.disabled = false;
      btn.classList.remove('is-waiting');
      btn.classList.remove('is-hold');
      btn.textContent = 'AI 代笔';
    }
    if (!pendingKeys(st).length) pollStop(st);
  }

  /* 封缄、重置这类「这一页要翻篇」的动作，把还按着的扣子都松开 */
  function waitClear(hud, root, st) {
    pendingKeys(st).forEach(function (k) { waitOff(hud, root, st, k); });
    pollStop(st);
  }

  function pollStart(hud, root, st) {
    if (st.poll) return;
    st.poll = setInterval(function () { pollTick(hud, root, st); }, POLL_MS);
    pollTick(hud, root, st);
  }

  function pollStop(st) {
    if (st.poll) { clearInterval(st.poll); st.poll = null; }
  }

  function pollTick(hud, root, st) {
    if (!pendingKeys(st).length) { pollStop(st); return; }
    var e = hud.api();
    if (!e || !e.messages || typeof e.messages.list !== 'function') return;
    Promise.resolve().then(function () { return e.messages.list(); })
      .then(function (list) { absorb(hud, root, st, lastSay(list)); })
      .catch(function () { /* 这一跳读不到就等下一跳；真没回还有超时兜底 */ });
  }

  /* 宿主肯在 AI 跑完一条时往卡里转事件，这条最快；不转也不碍事，轮询兜得住 */
  function bindRunEvents(hud, root, st) {
    if (st.evBound) return;
    var e = hud.api();
    if (!e || !e.events || typeof e.events.on !== 'function') return;
    st.evBound = true;
    try {
      e.events.on('agent.run.finished', function (p) {
        if (!pendingKeys(st).length) return;
        var t = p && p.message ? pickText(p.message) : '';
        if (t && absorb(hud, root, st, t)) return;
        pollTick(hud, root, st);
      });
    } catch (err) { st.evBound = false; }
  }

  /* 把一块代笔塞回它该去的那一栏，返回一句能直接摊给玩家看的话。 */
  function applyBlock(hud, root, s, raw) {
    var el = root.querySelector('[data-field="' + s.key + '"]');
    if (s.kind === 'list') {
      var items = splitList(hud, raw, LIST_CAP);
      if (!items.length) return '「' + s.label + '」那一块没解析出东西。';
      if (el) el.value = items.join('\n');
      return '「' + s.label + '」已取回 ' + items.length + ' 条：' + items.join('、') +
        '。不满意就改，或者再点一次「AI 代笔」。';
    }
    if (s.kind === 'number') {
      var got = oneLine(raw, 12), n = hud.num(got, NaN);
      if (!isFinite(n)) return '「' + s.label + '」那一块里没读出数字。';
      var lo = (s.min == null) ? n : s.min, hi = (s.max == null) ? n : s.max;
      var v = Math.round(hud.clamp(n, lo, hi));
      if (el) el.value = String(v);
      return '「' + s.label + '」已取回：' + v + (v !== Math.round(n) ? '（原样回的是 ' + Math.round(n) +
        '，按这一栏的范围夹住了）' : '') + '。';
    }
    var val = oneLine(raw, TEXT_CAP);
    if (!val) return '「' + s.label + '」那一块是空的。';
    if (el) el.value = val;
    return '「' + s.label + '」已取回：' + val;
  }

  /* 从一段回复里把还在等的栏位搬进栏。搬动了就返回 true。
     搬不动的（这一条里没写那一块）留在等待里 —— 下一次回复还有机会。 */
  function absorb(hud, root, st, text) {
    var labels = pendingKeys(st).filter(function (key) {
      return acceptable(text, st.base[key]);
    });
    if (!labels.length) return false;
    var blocks = parseBlocks(text), got = [], miss = [];
    labels.forEach(function (key) {
      var s = slotOf(hud, key);
      if (!s) return;
      if (blocks[s.label] == null && blocks[s.key] == null) { miss.push(s.label); return; }
      got.push(applyBlock(hud, root, s, blocks[s.label] != null ? blocks[s.label] : blocks[s.key]));
      waitOff(hud, root, st, key);
    });
    if (!got.length) return false;
    noteIn(root, 'AI 回完了 —— ' + got.join(' ') +
      (miss.length ? '这条里没写的：' + miss.join('、') + '（想再要一版就再点一次「AI 代笔」）。' : ''),
      'is-ok');
    return true;
  }

  /* ------------------------------------------------------------------ 动作 */

  function request(hud, root, st, key) {
    var s = slotOf(hud, key);
    if (!s) return;
    var cur = valueOf(hud, root, s);
    var text = MARK + '。现在是建卡阶段，不用写正文剧情，只回这一块。）\n' +
      '【代笔 · ' + s.label + '】\n' +
      '要求：' + wantOf(s) + '。' + tipOf(s) + '。\n' +
      (cur
        ? '他已经写了：' + cur + '\n（请在这份内容上润色 —— 保留他的意思与关键信息，不要另起炉灶。）'
        : '他还没写。\n（请替他想一版。）') + '\n' +
      '当前档案：' + contextOf(hud, root) + '\n' +
      '只回下面这一块，别的都不要写：\n' +
      '【代笔 · ' + s.label + '】\n（内容）';

    var e = hud.api();
    var caps = {
      input: !!(e && e.input && typeof e.input.set === 'function'),
      chat: !!(e && e.chat && typeof e.chat.send === 'function')
    };
    var mode = sendMode(caps, st.direct);
    st.lastReq = text;
    outIn(root, '<div class="hud-ai__req"><b>代笔请求</b>' +
      '<span class="hud-ai__hint">' + (mode === 'chat'
        ? '直接发出去；AI 回完自动搬进这一栏'
        : (mode === 'input' ? '会填进对话输入框 —— 你按发送；AI 回完自动搬进这一栏'
                            : '这一版宿主既不能代发、也填不了输入框 —— 把下面这段自己复制给 AI')) +
      '</span><button type="button" class="hud-btn hud-btn--quiet" data-act="ai-copy">' +
      '复制这段</button><pre class="hud-ai__pre">' + hud.esc(text) + '</pre></div>');

    if (!mode) {
      noteIn(root, '这一版宿主既不能代发、也填不了输入框 —— 把下面那段自己复制给 AI，回完再点「取回」。');
      return;
    }

    /* 先记下按下去这一刻的末条，再送 —— 顺序反了，AI 还没回时上一轮那条带
       【代笔】的回复会被当成新回复搬一遍。 */
    var shot = snapshot(hud, st, key);

    if (mode === 'input') {
      shot.then(function () { return hud.call('input.set', [text]); }).then(function () {
        waitOn(hud, root, st, key, true);
        noteIn(root, '请求已填进对话输入框 —— 你按发送；AI 回完自动搬进「' + s.label + '」。' +
          '（这样不会把你从建卡器那边卷走。）');
      }).catch(function (err) {
        waitOff(hud, root, st, key);
        if (!caps.chat) {
          noteIn(root, '填不进输入框（' + hud.msgOf(err) + '）—— 下面那段自己复制给 AI，回完点「取回」。',
            'is-error');
          return;
        }
        /* 输入框这条道不通（比如对话没在前台），退回直接发：总比什么都不做强 */
        hud.call('chat.send', [text]).then(function () {
          waitOn(hud, root, st, key, false);
          noteIn(root, '输入框这条路不通（' + hud.msgOf(err) + '），改成直接发 —— AI 回完自动搬进「' +
            s.label + '」。');
        }).catch(function (err2) {
          noteIn(root, '代笔请求没发出去：' + hud.msgOf(err2) + '。下面那段自己复制给 AI。', 'is-error');
        });
      });
      return;
    }

    shot.then(function () { return hud.call('chat.send', [text]); }).then(function () {
      waitOn(hud, root, st, key, false);
      noteIn(root, '代笔请求已发出 —— AI 回完自动搬进「' + s.label + '」。');
    }).catch(function (err) {
      waitOff(hud, root, st, key);
      noteIn(root, '代笔请求没发出去：' + hud.msgOf(err) + '。下面那段可以自己复制给 AI。', 'is-error');
    });
  }

  /* 取回前的三道门：桥读不读得到消息、末条是不是还停在我们自己的请求上、
     末条有没有内容。三道都过了才把正文交给 fn。 */
  function withLastSay(hud, root, fn) {
    var e = hud.api();
    if (!e || !e.messages || typeof e.messages.list !== 'function') {
      noteIn(root, '这一版宿主读不到消息，取不回代笔 —— 把 AI 那一段直接复制粘进栏里也一样。',
        'is-error');
      return;
    }
    Promise.resolve().then(function () {
      return e.messages.list();
    }).then(function (list) {
      var text = lastSay(list);
      if (!text) { noteIn(root, '读不到 AI 的回复（末条是空的）。', 'is-error'); return; }
      if (text.indexOf(MARK) >= 0) {
        noteIn(root, '末条还是我们自己发出去的请求 —— AI 那边还没回，等一下再点「取回」。', 'is-error');
        return;
      }
      fn(text);
    }).catch(function (err) { noteIn(root, '取回失败：' + hud.msgOf(err), 'is-error'); });
  }

  function take(hud, root, st, key) {
    var s = slotOf(hud, key);
    if (!s) return;
    withLastSay(hud, root, function (text) {
      var blocks = parseBlocks(text);
      if (blocks[s.label] == null && blocks[s.key] == null) {
        noteIn(root, 'AI 这条回复里没有【代笔 · ' + s.label + '】那一块 —— 要么它换了个栏位名，' +
          '要么这一栏它没写。也可以把它那段直接复制粘进来。', 'is-error');
        return;
      }
      noteIn(root, applyBlock(hud, root, s, blocks[s.label] != null ? blocks[s.label] : blocks[s.key]));
      waitOff(hud, root, st, key);   /* 手动取回来了，那颗「生成中…」也该松开 */
    });
  }

  function takeAll(hud, root, st) {
    withLastSay(hud, root, function (text) {
      var blocks = parseBlocks(text), done = [], miss = [];
      slots(hud).forEach(function (s) {
        if (blocks[s.label] == null && blocks[s.key] == null) { miss.push(s.label); return; }
        applyBlock(hud, root, s, blocks[s.label] != null ? blocks[s.label] : blocks[s.key]);
        waitOff(hud, root, st, s.key);
        done.push(s.label);
      });
      if (!done.length) {
        noteIn(root, '这条回复里一块【代笔 · 〈栏位名〉】都没有 —— 看看它是不是没照格式回。', 'is-error');
        return;
      }
      noteIn(root, '已取回：' + done.join('、') + '。' +
        (miss.length ? '这条里没写的：' + miss.join('、') + '。' : ''), 'is-ok');
    });
  }

  /* 把最近那份请求抄到剪贴板 —— 宿主不让写剪贴板时如实说，让人自己框选 */
  function copyReq(hud, root, st) {
    if (!st.lastReq) {
      noteIn(root, '还没有请求可抄 —— 先点某一栏的「AI 代笔」。', 'is-error');
      return;
    }
    var noWay = '这一版不让脚本写剪贴板 —— 把下面那段用鼠标框住，按 Ctrl+C。';
    try {
      if (window.navigator && window.navigator.clipboard &&
          typeof window.navigator.clipboard.writeText === 'function') {
        window.navigator.clipboard.writeText(st.lastReq).then(function () {
          noteIn(root, '已抄走 —— 粘进对话输入框就行。', 'is-ok');
        }).catch(function () { noteIn(root, noWay, 'is-error'); });
        return;
      }
    } catch (err) { /* 落到下面 */ }
    noteIn(root, noWay, 'is-error');
  }

  /* 默认「只填不送」：一按发送宿主就把对话卷到最底下，而建卡器长在开场那一条里，
     人得自己爬回来。想省这次回车的人，把开关拨到「直接发」。 */
  function directToggle(hud, root, st, btn) {
    st.direct = !st.direct;
    if (btn) btn.textContent = '代笔：' + (st.direct ? '直接发' : '只填不送');
    noteIn(root, st.direct
      ? '代笔请求会直接发出去 —— 发完对话可能被卷到最底下（建卡器在开场那一条里，翻回去就有）。'
      : '代笔请求只填进对话输入框，你自己按发送 —— 这样不会把你从建卡器那边卷走。');
  }

  /* ------------------------------------------------------------------ 接线 */

  function register() {
