      per: hud.num(cfg.per, 5),
      base: Math.max(0, Math.round(hud.num(cfg.base, 1))),
      level: hud.str(cfg.level) || '等级',
      bonus: hud.str(cfg.bonus) || '永久奖励',
      add: hud.str(cfg.add) || '加成',
      job: hud.str(cfg.job) || '职业',
