  /* 把 total 点按权重分给六项：最大余数法 —— 先按比例取整，
     剩下的点给小数部分最大的那几项（并列时靠前的先拿）。
     总和**正好**等于 total，不超支也不剩 —— 这条在自检里钉死。 */
  function spread(total, weights) {
    var n = weights.length, out = [], frac = [], i;
    var left = Math.round(toNum(total, 0));
